// The exercise catalog is GENERATED by the Python model (tools/export_catalog.py) so the
// website and the tracker can never disagree about an exercise's angle, bounds or defaults.
import raw from '../data/exerciseCatalog.json';

export const SCHEMA_MAJOR = String(raw.schema_version).split('.')[0];
export const CATALOG = raw.exercises;
export const BY_KEY = Object.fromEntries(CATALOG.map((e) => [e.key, e]));
export const GROUPS = [...new Set(CATALOG.map((e) => e.group))];

export const exerciseName = (key) => (BY_KEY[key] ? BY_KEY[key].name : key);

// Human wording for the flags the tracker can attach to a repetition.
const BUILT_IN_FLAGS = {
  short_of_target: 'Did not reach the target angle',
  too_fast: 'Repetition too fast',
  too_slow: 'Repetition too slow',
  hold_short: 'Hold shorter than prescribed',
  tracking_lost: 'Tracking lost during repetition',
};

export function flagLabel(flag, exerciseKey) {
  if (BUILT_IN_FLAGS[flag]) return BUILT_IN_FLAGS[flag];
  const check = (BY_KEY[exerciseKey]?.form_checks || []).find((c) => c.key === flag);
  return check ? check.message : flag;
}
